<?php
declare(strict_types=1);

/**
 * Products → per-standard tables Transform
 *
 * Routes each product to its target table based on the productfeed_standard
 * of its feed, then upserts all non-raw_data columns plus the raw_data fields
 * expanded as individual columns.
 *
 * Usage:
 *   php transform_products.php [--dry-run] [--batch=N]
 *
 * Requires products_search_schema.json (generated by setup_products_search.php).
 */

$dryRun    = in_array('--dry-run', $argv ?? [], true);
$batchSize = 1000;
foreach ($argv ?? [] as $arg) {
    if (preg_match('/^--batch=(\d+)$/', $arg, $m)) {
        $batchSize = max(1, (int) $m[1]);
        break;
    }
}

$sourceCfg = require __DIR__ . '/config.php';
$db        = $sourceCfg['db'];
define('TABLE_PREFIX', $db['table_prefix'] ?? '');

// Columns copied directly from products (no transformation).
const DIRECT_COLS = [
    'id', 'feed_id', 'program_id', 'title', 'description',
    'offer_count', 'lowest_price', 'in_stock', 'currency_code',
    'language_code', 'image', 'attributes', 'program_ids', 'standard_ids',
];

// Per-table override: only these products columns are copied for the given table.
// Tables not listed here use DIRECT_COLS.
const TABLE_DIRECT_COLS = [
    'products_accomodations' => ['id', 'feed_id', 'program_id', 'title', 'description', 'lowest_price'],
    'products_transport'     => ['id', 'feed_id', 'program_id', 'title', 'lowest_price'],
];

// Per-table columns that require boolean transformation before insert.
// Mapping: 0 => NULL, false => 0, true => 1, NULL => NULL
const BOOLEAN_FIELDS = [
    'products_accommodations_transport' => ['discount', 'trip_lastminute'],
    'products_accomodations' => ['accommodation_child_friendly', 'accommodation_pets_allowed', 
        'accommodation_smoking_allowed', 'has_airco', 'has_barbecue', 'has_electricity', 'has_internet', 'has_sauna', 
        'has_swimmingpool', 'has_washingmachine', 'discount', 'trip_lastminute'
    ],
];

// Per-table date columns where past dates are replaced with NULL before insert.
const FUTURE_DATE_FIELDS = [
    'products_accommodations_transport' => ['arrival_date', 'departure_date', 'departure_date_return'],
    'products_accomodations' => ['accommodation_lowest_date', 'arrival_date', 'departure_date',],
    'products_transport' => ['arrival_date', 'departure_date', 'departure_date_return'],
];

// Per-table columns that require normalisation to IATA airport codes before insert.
const IATA_FIELDS = [
    'products_accommodations_transport' => [
        'airport_departure', 'airportcode_departure',
        'airportcode_destination', 'airportcode_destination_return',
    ],
    'products_transport' => [
        'airport_departure', 'airport_destination', 
        'airportcode_departure', 'airportcode_destination',
    ],
];

const IATA_MAP = [
    'amst'               => 'AMS',
    'amsterdam'          => 'AMS',
    'brus'               => 'BRU',
    'brussel charleroi'  => 'CRL',
    'brussel zaventem'   => 'BRU',
    'dort'               => 'DTM',
    'dortmund'           => 'DTM',
    'duss'               => 'DUS',
    'dusseldorf'         => 'DUS',
    'eind'               => 'EIN',
    'eindhoven'          => 'EIN',
    'fran'               => 'FRA',
    'frankfurt hahn'     => 'FRA',
    'keul'               => 'CGN',
    'keulen'             => 'CGN',
    'luxe'               => 'LUX',
    'luxemburg'          => 'LUX',
    'maas'               => 'MST',
    'maastricht'         => 'MST',
    'muns'               => 'FMO',
    'munster'            => 'FMO',
    'rott'               => 'RTM',
    'rotterdam'          => 'RTM',
    'weez'               => 'NRN',
    'weeze'              => 'NRN',
];

// Per-table columns that require normalisation to ISO country codes before insert.
const COUNTRY_FIELDS = [
    'products_accommodations_transport' => ['departure_country', 'destination_country'],
    'products_accomodations' => ['destination_country'],
    'products_transport' => ['destination_country'],
];

const COUNTRY_MAP = [
    'vs' => 'US',
];

// Per-table columns that require normalisation to star classification (1–5) before insert.
const STAR_RATING_FIELDS = [
    'products_accommodations_transport' => ['star_rating'],
    'products_accomodations' => ['star_rating'],
];

// Per-table columns that require normalisation to transport type codes before insert.
const TRANSPORT_TYPE_FIELDS = [
    'products_accommodations_transport' => ['travel_transportation_type'],
    'products_transport' => ['travel_transportation_type'],
];

const TRANSPORT_TYPE_MAP = [
    'boat'          => 'bo',
    'bus'           => 'bu',
    'by own means'  => 'au',
    'flight'        => 'vl',
    'train'         => 'tr',
];

// Per-table columns that require normalisation to trip type codes before insert.
const TRIP_TYPE_FIELDS = [
    'products_accommodations_transport' => ['travel_trip_type'],
    'products_accomodations' => ['travel_trip_type'],
];

// Keys are lowercase values after stripping any trailing comma.
const TRIP_TYPE_MAP = [
    'all inclusive'      => 'AI',
    'fb'                 => 'VP',
    'hb'                 => 'HP',
    'halfpension'        => 'HP',
    'logies en ontbijt'  => 'LO',
    'logies'             => 'LG',
    'ph'                 => 'HP',
    'pv'                 => 'VP',
    'uai'                => 'AI',
    'volpension'         => 'VP',
    'half pension plus'  => 'HP',
];

// ── Helpers ────────────────────────────────────────────────────────────────

function connectDb(array $db): PDO
{
    $dsn = "mysql:host={$db['host']};dbname={$db['name']};charset={$db['charset']}";
    return new PDO($dsn, $db['user'], $db['pass'], [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    ]);
}

function log_msg(string $msg): void
{
    echo '[' . date('H:i:s') . '] ' . $msg . "\n";
}

function log_section(string $title): void
{
    echo "\n" . str_repeat('─', 60) . "\n  $title\n" . str_repeat('─', 60) . "\n";
}

function transformBoolean(mixed $val): int|null
{
    if ($val === null)                                              return null;
    if ($val === 0 || $val === '0')                                return null;
    if ($val === false || strtolower((string) $val) === 'false')   return 0;
    if ($val === true  || strtolower((string) $val) === 'true')    return 1;
    return null;
}

function transformTripType(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    $normalized = strtolower(trim(rtrim(trim((string) $val), ',')));
    return TRIP_TYPE_MAP[$normalized] ?? null;
}

function transformTransportType(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    return TRANSPORT_TYPE_MAP[strtolower(trim((string) $val))] ?? null;
}

function transformStarRating(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    $n = (int) $val;
    if ($n < 1) return null;
    return (string) min($n, 5);
}

function transformCountry(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    return COUNTRY_MAP[strtolower(trim((string) $val))] ?? (string) $val;
}

function transformIata(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    return IATA_MAP[strtolower(trim((string) $val))] ?? (string) $val;
}

function transformFutureDate(mixed $val): string|null
{
    if ($val === null || $val === '') return null;
    $ts = strtotime((string) $val);
    if ($ts === false) return null;
    return $ts >= strtotime('today') ? (string) $val : null;
}

function buildUpsertSql(string $tableName, array $allCols): string
{
    $colNames     = implode(', ', array_map(fn($c) => "`$c`", $allCols));
    $placeholders = implode(', ', array_map(fn($c) => ":$c", $allCols));
    $updates      = implode(', ', array_map(fn($c) => "`$c` = VALUES(`$c`)", $allCols));
    $physTable    = TABLE_PREFIX . $tableName;
    return "INSERT INTO `$physTable` ($colNames) VALUES ($placeholders) ON DUPLICATE KEY UPDATE $updates";
}

// ── Load schema ────────────────────────────────────────────────────────────

$schemaFile = __DIR__ . '/products_search_schema.json';
if (!file_exists($schemaFile)) {
    echo "ERROR: $schemaFile not found.\nRun php setup_products_search.php first.\n";
    exit(1);
}
$schema = json_decode((string) file_get_contents($schemaFile), true);
$tables = $schema['tables'] ?? [];
// $tables: ['products_general' => ['standard_id' => 1, 'extra_cols' => [...]], ...]

if (empty($tables)) {
    echo "ERROR: No tables defined in schema.\n";
    exit(1);
}

if ($dryRun) {
    echo "[DRY RUN — no writes]\n";
}

// ── Connect ────────────────────────────────────────────────────────────────

log_section('Products → per-standard tables');
log_msg('Connecting to DB (' . $db['name'] . ')...');
$pdo = connectDb($db);

// ── Build lookup: standard_id → table_name ────────────────────────────────

$standardToTable = []; // int => string
foreach ($tables as $tableName => $info) {
    $standardToTable[(int) $info['standard_id']] = $tableName;
}
log_msg('Tables: ' . implode(', ', array_values($standardToTable)));

// ── Build lookup: feed_id → standard_id ───────────────────────────────────

log_msg('Loading feed → standard mapping...');
$feedToStandard = []; // int => int|null
$stmt = $pdo->query("SELECT id, standard_id FROM `" . TABLE_PREFIX . "productfeeds`");
while ($row = $stmt->fetch()) {
    $feedToStandard[(int) $row['id']] = isset($row['standard_id']) ? (int) $row['standard_id'] : null;
}
log_msg('Feeds loaded: ' . count($feedToStandard));

// ── Prepare per-table upsert statements ───────────────────────────────────

$upsertStmts    = []; // table_name => PDOStatement|null
$tableExtraCols  = []; // table_name => [['col','orig_key'], ...]
$tableDirectCols = []; // table_name => string[]

foreach ($tables as $tableName => $info) {
    $extraCols                   = $info['extra_cols'];
    $tableExtraCols[$tableName]  = $extraCols;
    $directCols                  = TABLE_DIRECT_COLS[$tableName] ?? DIRECT_COLS;
    $tableDirectCols[$tableName] = $directCols;
    $allCols                     = array_merge($directCols, array_column($extraCols, 'col'));
    $sql                         = buildUpsertSql($tableName, $allCols);
    $upsertStmts[$tableName]     = $dryRun ? null : $pdo->prepare($sql);
}

// ── Count & stream ─────────────────────────────────────────────────────────

$total = (int) $pdo->query("SELECT COUNT(*) FROM `" . TABLE_PREFIX . "products`")->fetchColumn();
log_msg("Source rows: $total  |  batch: $batchSize");

if ($total === 0) {
    log_msg('Nothing to process.');
    exit(0);
}

$processed = 0;
$skipped   = 0;
$errors    = 0;
$offset    = 0;
$counts    = array_fill_keys(array_keys($tables), 0); // per-table row counts
$start     = time();

while ($offset < $total) {
    $rows = $pdo->query(
        "SELECT * FROM `" . TABLE_PREFIX . "products` LIMIT {$batchSize} OFFSET {$offset}"
    )->fetchAll();

    if (empty($rows)) break;

    foreach ($rows as $row) {
        // Resolve target table via feed → standard.
        $feedId     = (int) ($row['feed_id'] ?? 0);
        $standardId = $feedToStandard[$feedId] ?? null;
        $tableName  = $standardId !== null ? ($standardToTable[$standardId] ?? null) : null;

        if ($tableName === null) {
            $skipped++;
            continue;
        }

        // Decode raw_data; normalise keys to lowercase.
        $rawData = [];
        if (!empty($row['raw_data'])) {
            $decoded = json_decode((string) $row['raw_data'], true);
            if (is_array($decoded)) {
                foreach ($decoded as $k => $v) {
                    $rawData[strtolower(trim((string) $k))] = $v;
                }
            }
        }

        // Build target row.
        $target = [];
        foreach ($tableDirectCols[$tableName] as $col) {
            $target[$col] = $row[$col] ?? null;
        }
        foreach ($tableExtraCols[$tableName] as $extra) {
            $val = $rawData[$extra['orig_key']] ?? null;
            if (is_array($val)) {
                $target[$extra['col']] = json_encode($val, JSON_UNESCAPED_UNICODE);
            } elseif (($extra['type'] ?? '') === 'JSON' && $val !== null) {
                // Scalar in a JSON column must be valid JSON or MariaDB rejects it.
                $target[$extra['col']] = json_encode($val, JSON_UNESCAPED_UNICODE);
            } else {
                $target[$extra['col']] = $val;
            }
        }

        // Apply boolean transformation for designated columns.
        foreach (BOOLEAN_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformBoolean($target[$col]);
            }
        }

        // Nullify past dates for designated date columns.
        foreach (FUTURE_DATE_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformFutureDate($target[$col]);
            }
        }

        // Normalise airport codes to IATA for designated columns.
        foreach (IATA_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformIata($target[$col]);
            }
        }

        // Normalise country codes to ISO for designated columns.
        foreach (COUNTRY_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformCountry($target[$col]);
            }
        }

        // Normalise star rating to 1–5 scale for designated columns.
        foreach (STAR_RATING_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformStarRating($target[$col]);
            }
        }

        // Normalise transport type to standard codes for designated columns.
        foreach (TRANSPORT_TYPE_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformTransportType($target[$col]);
            }
        }

        // Normalise trip type to standard codes for designated columns.
        foreach (TRIP_TYPE_FIELDS[$tableName] ?? [] as $col) {
            if (array_key_exists($col, $target)) {
                $target[$col] = transformTripType($target[$col]);
            }
        }

        if ($dryRun) {
            $processed++;
            $counts[$tableName]++;
            continue;
        }

        try {
            $upsertStmts[$tableName]->execute($target);
            $processed++;
            $counts[$tableName]++;
        } catch (PDOException $e) {
            $errors++;
            if ($errors <= 10) {
                log_msg("  ERROR id={$row['id']} → $tableName: " . $e->getMessage());
            }
            if (str_contains($e->getMessage(), '2006') || str_contains($e->getMessage(), 'gone away')) {
                $pdo = connectDb($db);
                foreach ($tables as $tbl => $info) {
                    $directCols = TABLE_DIRECT_COLS[$tbl] ?? DIRECT_COLS;
                    $allCols    = array_merge($directCols, array_column($info['extra_cols'], 'col'));
                    $upsertStmts[$tbl] = $pdo->prepare(buildUpsertSql($tbl, $allCols));
                }
            }
        }
    }

    $offset += $batchSize;

    $elapsed = max(1, time() - $start);
    $rate    = round($processed / $elapsed);
    $pct     = round(($processed + $skipped) / $total * 100, 1);
    log_msg(sprintf('Progress: %d / %d (%s%%)  %d rows/s%s%s',
        $processed + $skipped, $total, $pct, $rate,
        $skipped > 0 ? "  [skipped: $skipped]" : '',
        $errors  > 0 ? "  [errors: $errors]"   : ''
    ));
}

// ── Summary ────────────────────────────────────────────────────────────────

$elapsed = time() - $start;
echo "\n";
log_msg(sprintf('Complete in %02d:%02d%s%s',
    intdiv($elapsed, 60), $elapsed % 60,
    $errors  > 0 ? "  ($errors errors)"  : '',
    $dryRun       ? '  [DRY RUN]'         : ''
));
log_msg(sprintf('Processed: %d  |  Skipped (no matching standard): %d', $processed, $skipped));
foreach ($counts as $tbl => $n) {
    log_msg(sprintf('  %-40s %d rows', $tbl, $n));
}
